test('Every main route renders without exceptions and contains its primary interaction',()=>{for(const [hash,find]of [['home','Conquista el núcleo'],['arena','code-a'],['puzzles','answer'],['learn','lesson-complete'],['tournaments','prepare-live'],['warriors','Crear guerrero'],['settings','Exportar todo']]){const a=app('#'+hash);assert.ok(a.root.innerHTML.includes(find),hash);assert.ok(a.root.innerHTML.includes('Creado por Sara y Pascal'));}});
test('Daily puzzle accepts an executed solution and saves progress across reload',async()=>{const a=app('#home');await a.click('solution-puzzle');await a.click('check-puzzle');const saved=JSON.parse(a.storage.get('ogun-v1'));assert.equal(Object.values(saved.solved).filter(Boolean).length,1);const reloaded=app('#home',saved);assert.ok(reloaded.root.innerHTML.includes('RESUELTO'));});
test('Malformed puzzle input is shown inline, without changing saved progress',async()=>{const a=app('#puzzles');a.input('answer','abc');await a.click('check-puzzle');assert.ok(a.elements.get('puzzle-feedback').innerHTML.includes('número entero'));});
test('Practice replaces puzzle and daily selection returns to the selected date',async()=>{const a=app('#puzzles');await a.click('new-puzzle');assert.ok(a.root.innerHTML.includes('Siguiente reto'));await a.click('daily-slot',{slot:'1'});assert.ok(!a.root.innerHTML.includes('Siguiente reto'));a.change('puzzle-date','2026-05-10');assert.ok(a.root.innerHTML.includes('2026-05-10'));});
test('Lesson navigation, executed exercise and completion survive reload',async()=>{const a=app('#learn');await a.click('lesson',{index:'3'});assert.ok(a.root.innerHTML.includes('Saltar sin caer'));await a.click('solution-puzzle');await a.click('check-puzzle');await a.click('lesson-complete');assert.ok(JSON.parse(a.storage.get('ogun-v1')).lessons.includes(3));await a.click('lesson-next');assert.ok(a.root.innerHTML.includes('Aritmética y campos'));});
test('Arena validates, runs, pauses, inspects and repeats the same seed',async()=>{const a=app('#arena');await a.click('validate-code',{side:'a'});assert.ok(a.elements.get('validation-a').textContent.includes('✓'));a.change('cfg-seed','repeat-me');await a.click('step-battle');const info=a.elements.get('load-info').textContent;assert.ok(info.includes('repeat-me'));assert.equal(a.elements.get('turn-count').textContent,'1');await a.click('run-battle');a.tick(100);assert.ok(Number(a.elements.get('turn-count').textContent.replace(/\./g,''))>1);await a.click('run-battle');a.input('inspect-index','1');assert.ok(a.elements.get('inspect-text').textContent.includes('@1'));await a.click('replay-battle');assert.equal(a.elements.get('load-info').textContent,info);assert.equal(a.elements.get('turn-count').textContent,'0');});
test('Code changes invalidate the loaded battle and preserve draft code',async()=>{const a=app('#arena');await a.click('step-battle');a.input('code-a',';name Test\nJMP 0');assert.ok(a.elements.get('battle-result').textContent.includes('modificado'));await a.click('validate-code',{side:'a'});assert.ok(a.elements.get('validation-a').textContent.includes('Test'));const saved=JSON.parse(a.storage.get('ogun-v1'));assert.equal(saved.draft.a,';name Test\nJMP 0');});
test('Finished matches persist and can be replayed from history',async()=>{const a=app('#arena');a.input('code-a','DAT 0,0');a.change('cfg-firstWarrior','A');await a.click('step-battle');const saved=JSON.parse(a.storage.get('ogun-v1'));assert.equal(saved.history.length,1);assert.ok(saved.history[0].result.includes('Gana'));await a.click('history-replay',{index:'0'});assert.equal(a.elements.get('turn-count').textContent,'0');});
test('Save warrior, search library, load as B, and export its source',async()=>{const a=app('#arena');a.input('code-a',';name Mi prueba\nJMP 0');await a.click('save-warrior',{side:'a'});const saved=JSON.parse(a.storage.get('ogun-v1'));assert.equal(saved.custom.length,1);a.navigate('warriors');a.input('warrior-search','Mi prueba');assert.ok(a.root.innerHTML.includes('Mi prueba'));await a.click('load-warrior',{id:saved.custom[0].id,side:'b'});assert.equal(a.elements.get('code-b').value,';name Mi prueba\nJMP 0');await a.click('export-warrior',{side:'b'});assert.ok(a.downloads.includes('guerrero-B.red'));});
test('Shared URL opens the exact original battle and can be randomized afresh',async()=>{const a=app('#arena');a.change('cfg-seed','shared');await a.click('step-battle');await a.click('share-battle');assert.ok(a.ctx.clipboard.includes('#battle='));const imported=app('#'+a.ctx.clipboard.split('#')[1]);assert.ok(imported.elements.get('load-info').textContent.includes('shared'));await imported.click('new-battle');assert.ok(!imported.elements.get('load-info').textContent.includes('shared'));});
test('Malformed shared URL is reported and arena remains usable',()=>{const a=app('#battle=bad');assert.ok(a.root.innerHTML.includes('Arena'));assert.ok(a.toast.textContent.includes('No se pudo abrir'));});
test('Tournament runs real worker code, persists scores, exports and replays a round',async()=>{const a=app('#tournaments');await a.click('tournament-examples');a.change('t-turns','100');await a.click('start-tournament');const saved=JSON.parse(a.storage.get('ogun-v1'));assert.equal(saved.tournaments.length,1);assert.equal(saved.tournaments[0].matches.length,6);await a.click('export-tournament');assert.ok(a.downloads.includes('ogun-torneo.json'));await a.click('replay-tournament',{match:'0',game:'0'});assert.ok(a.elements.get('load-info').textContent.includes('Empieza A'));});
test('Theme, larger type, reduced motion and contrast update persisted preferences',()=>{const a=app('#settings');a.change('pref-theme','light');a.change('pref-size','22');a.change('pref-reduced',true);a.change('pref-contrast',true);assert.equal(a.ctx.document.body.dataset.theme,'light');const saved=JSON.parse(decodeURIComponent(a.cookieJar.get('ogun_prefs')));assert.equal(saved.size,22);assert.equal(saved.reduced,true);assert.equal(saved.contrast,true);assert.equal(JSON.parse(a.storage.get('ogun-v1')).prefs,undefined);});
test('Backup export is available and hostile warrior names are escaped',async()=>{const a=app('#arena');a.input('code-a',';name <img src=x onerror=alert(1)>\nJMP 0');await a.click('save-warrior',{side:'a'});a.navigate('warriors');a.input('warrior-search','<img');assert.ok(a.root.innerHTML.includes('&lt;img'));assert.ok(!a.root.innerHTML.includes('<img src=x'));a.navigate('settings');await a.click('export-data');assert.ok(a.downloads.includes('ogun-mis-datos.json'));});
const red=(name,code)=>({name,size:code.length,async text(){return code;}});
test('Tournament multi-upload shows accepted and rejected files and admits only valid code',async()=>{const a=app('#tournaments');await a.upload([red('a.red',';name Alpha\nMOV.I 0,1'),red('b.red',';name Beta\nJMP 0'),red('bad.red','UNKNOWN #1,#2')]);assert.ok(a.root.innerHTML.includes('Alpha'));assert.ok(a.root.innerHTML.includes('Beta'));assert.ok(a.root.innerHTML.includes('rejected'));assert.ok(a.root.innerHTML.includes('Cumple las reglas'));a.change('t-turns','40');await a.click('start-tournament');const t=JSON.parse(a.storage.get('ogun-v1')).tournaments[0];assert.equal(t.entries.length,2);assert.equal(t.format,'swiss');assert.equal(t.stages.length,1);assert.ok(!t.entries.some(e=>e.filename==='bad.red'));});
test('Rule changes revalidate previously uploaded guerreros and persist in session cookies',async()=>{const a=app('#tournaments');await a.upload([red('multi.red',';name Multi\nSPL 0\nJMP 0')]);a.change('t-banned','SPL');assert.ok(a.elements.get('participants').innerHTML.includes('fuera de las reglas: SPL'));a.change('t-banned','');a.change('t-length','1');assert.ok(a.elements.get('participants').innerHTML.includes('MAXLENGTH'));const rules=JSON.parse(decodeURIComponent(a.cookieJar.get('ogun_tournament')));assert.equal(rules.maxLength,1);const b=app('#tournaments',null,a.cookieJar,a.sessionMap);assert.equal(b.elements.get('t-length').value,'1');assert.ok(b.root.innerHTML.includes('Multi'));});
test('Session cookies restore detailed presentation without writing preferences to durable progress',()=>{const a=app('#settings');a.change('pref-coreShape','wide');a.change('pref-resultDuration','0');a.change('pref-resultSize','60');a.change('pref-tournamentFx','off');a.change('pref-background','off');assert.ok(!a.ctx.lastCookie.includes('Expires='));assert.ok(!a.ctx.lastCookie.includes('Max-Age='));assert.ok(a.ctx.lastCookie.includes('SameSite=Lax'));assert.ok(a.ctx.lastCookie.includes('Secure'));const b=app('#settings',null,a.cookieJar);assert.equal(b.elements.get('pref-coreShape').value,'wide');assert.equal(b.elements.get('pref-resultDuration').value,'0');assert.equal(b.elements.get('pref-resultSize').value,'60');assert.equal(b.elements.get('pref-tournamentFx').value,'off');const fresh=app('#settings');assert.equal(fresh.elements.get('pref-coreShape').value,'square');assert.equal(fresh.elements.get('pref-resultDuration').value,'3500');});
test('Winner and draw previews use warrior names and configurable static presentation',async()=>{const a=app('#settings');a.change('pref-resultStyle','still');a.change('pref-resultSize','60');await a.click('preview-win');assert.ok(a.resultLayer.innerHTML.includes('Mi guerrero'));assert.equal(a.resultLayer.dataset.effect,'still');a.dismiss();await a.click('preview-draw');assert.ok(a.resultLayer.innerHTML.includes('EMPATE'));assert.ok(a.resultLayer.innerHTML.includes('Guerrero A · Guerrero B'));});
test('An arena finish displays the victorious warrior and honors the disable control',async()=>{const a=app('#arena');a.input('code-a',';name Mortal\nDAT 0,0');a.input('code-b',';name Superviviente\nJMP 0');a.change('cfg-firstWarrior','A');await a.click('step-battle');assert.ok(a.resultLayer.innerHTML.includes('Superviviente'));a.dismiss();a.navigate('settings');a.change('pref-arenaFx',false);a.navigate('arena');await a.click('replay-battle');a.resultLayer.innerHTML='';await a.click('step-battle');assert.equal(a.resultLayer.innerHTML,'');});
test('Arena and tournament use the same customizable tie outcome',async()=>{const a=app('#arena');a.input('code-a',';name Copista\nMOV.I 0,1');a.input('code-b',';name Bucle\nJMP 0');a.change('cfg-firstWarrior','A');a.change('cfg-maxCycles','10');a.change('cfg-drawPolicy','territory');await a.click('batch-battle');const g=JSON.parse(a.storage.get('ogun-v1')).history[0];assert.equal(g.result,'Gana Copista');assert.ok(a.resultLayer.innerHTML.includes('Desempate por celdas'));});
test('Square core has square intrinsic dimensions; custom panoramic shape changes both dimensions',()=>{const a=app('#arena');assert.equal(a.elements.get('core-canvas').width,a.elements.get('core-canvas').height);a.navigate('settings');a.change('pref-coreShape','wide');a.navigate('arena');assert.notEqual(a.elements.get('core-canvas').width,a.elements.get('core-canvas').height);});
test('Complete motion shutdown disables background, core updates and animated result styles',async()=>{const a=app('#settings');await a.click('disable-motion');const p=JSON.parse(decodeURIComponent(a.cookieJar.get('ogun_prefs')));assert.equal(p.reduced,true);assert.equal(p.coreMotion,false);assert.equal(p.background,'off');assert.equal(p.resultStyle,'still');assert.equal(p.resultParticles,0);});
test('Tournament final displays a champion or tied leaders; disabled announcements remain absent',async()=>{const a=app('#settings');a.change('pref-tournamentFx','off');a.navigate('tournaments');await a.click('tournament-examples');a.change('t-turns','10');await a.click('start-tournament');assert.equal(a.resultLayer.innerHTML,'');const b=app('#tournaments');await b.upload([red('loop1.red',';name Uno\nJMP 0'),red('loop2.red',';name Dos\nJMP 0')]);b.change('t-turns','10');await b.click('start-tournament');assert.ok(b.resultLayer.innerHTML.includes('TORNEO EMPATADO'));assert.ok(b.resultLayer.innerHTML.includes('Uno'));assert.ok(b.resultLayer.innerHTML.includes('Dos'));});
async function liveSetup(n=4,format='knockout',extra={}){const a=app('#tournaments');await a.upload(Array.from({length:n},(_,i)=>red(`person-${i}.red`,`;name Warrior ${i}\nJMP 0`)));a.change('t-format',format);a.change('t-turns','6');a.change('t-rounds','2');a.change('t-knockout-tie','seeded');a.change('t-countdown','0');a.change('t-intermission','0');a.change('t-live-announcements','off');for(const[id,value]of Object.entries(extra))a.change(id,value);await a.click('prepare-live');assert.ok(a.storage.has('ogun_live_v1'),a.toast.textContent);return a;}
const readLive=a=>JSON.parse(a.storage.get('ogun_live_v1'));
async function playToEnd(a,max=1000){await a.click('live-play');for(let i=0;i<max;i++){a.advance(80);a.dismiss();const state=readLive(a);if(a.ctx.OgunLive.view(state).complete)return state;}assert.fail('Live tournament did not finish: '+a.toast.textContent);}
test('Preparing a live five-player bracket draws SVG paths and grants BYEs before any combat',async()=>{const a=await liveSetup(5),s=readLive(a),v=a.ctx.OgunLive.view(s);assert.equal(Object.keys(s.results).length,0);assert.equal(v.matches.filter(m=>m.status==='bye').length,3);assert.ok(a.root.innerHTML.includes('bracket-connectors'));assert.ok(a.root.innerHTML.includes('PASE AUTOMÁTICO'));assert.ok(a.root.innerHTML.includes('Comenzar espectáculo'));assert.ok(a.root.innerHTML.includes('Clasificación'));assert.ok(a.root.innerHTML.includes('Historial de duelos'));});
test('Countdown displays 3, 2, 1 and the tournament can pause and resume it',async()=>{const a=await liveSetup(2,'knockout',{'t-countdown':'3'});await a.click('live-play');a.advance(80);assert.equal(a.elements.get('stage-countdown').textContent,'3');a.advance(1000);assert.equal(a.elements.get('stage-countdown').textContent,'2');await a.click('live-pause');a.advance(10000);assert.equal(Object.keys(readLive(a).results).length,0);await a.click('live-play');a.advance(1000);assert.equal(a.elements.get('stage-countdown').textContent,'1');for(let i=0;i<20;i++)a.advance(80);assert.ok(a.ctx.OgunLive.view(readLive(a)).complete);});
test('Live autoplay executes actual battles and reaches a champion without organizer intervention',async()=>{const a=await liveSetup(8),s=await playToEnd(a),v=a.ctx.OgunLive.view(s);assert.equal(Object.keys(s.results).length,7);assert.ok(v.champion);assert.ok(Object.values(s.results).every(r=>r.games.length===2));assert.ok(a.elements.get('tournament-results').innerHTML.includes('CAMPEÓN'));assert.ok(a.elements.get('tournament-results').innerHTML.includes('Cuartos'));assert.ok(a.elements.get('tournament-results').innerHTML.includes('Semifinales'));});
test('Manual pacing executes one selected match and waits for the next explicit launch',async()=>{const a=await liveSetup(4,'knockout',{'t-auto':false}),v=a.ctx.OgunLive.view(readLive(a)),m=v.matches.find(m=>m.status==='ready');await a.click('live-match',{id:m.id});for(let i=0;i<30;i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,1);assert.equal(a.ctx.OgunLive.view(readLive(a)).complete,false);await a.click('live-next');for(let i=0;i<30;i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,2);});
test('A checkpoint restores completed games and resumes only pending work',async()=>{const a=await liveSetup(4,'knockout',{'t-auto':false});await a.click('live-play');for(let i=0;i<30;i++)a.advance(80);const before=readLive(a);assert.equal(Object.keys(before.results).length,1);const b=app('#tournaments',null,a.cookieJar,a.sessionMap,a.storage);assert.ok(b.root.innerHTML.includes('Reanudar')||b.root.innerHTML.includes('Comenzar espectáculo'));assert.equal(Object.keys(readLive(b).results).length,1);await b.click('live-play');for(let i=0;i<30;i++)b.advance(80);assert.equal(Object.keys(readLive(b).results).length,2);});
test('Organizer can correct an earlier result, invalidate dependent games and undo that correction',async()=>{const a=await liveSetup(4),before=await playToEnd(a),v=a.ctx.OgunLive.view(before),m=v.matches.find(m=>m.result);a.change('live-edit-match',m.id);a.input('live-edit-a','1');a.input('live-edit-b','1');a.input('live-edit-draw','0');a.change('live-edit-winner',m.winnerId===m.aId?'B':'A');a.input('live-edit-reason','Se invirtió el marcador');await a.click('live-correct');const after=readLive(a);assert.equal(after.results[m.id].manual,true);assert.equal(a.ctx.OgunLive.view(after).complete,false);assert.ok(Object.keys(after.audit.at(-1).discarded).length);await a.click('live-undo');assert.equal(a.ctx.OgunLive.view(readLive(a)).champion,v.champion);});
test('Organizer changes a participant name and league points with an audit trail',async()=>{const a=await liveSetup(4,'league'),entry=readLive(a).entries[0];a.change('live-edit-person',entry.id);a.input('live-edit-owner','Equipo Pascal');await a.click('live-rename');assert.ok(a.elements.get('tournament-results').innerHTML.includes('Equipo Pascal'));a.input('live-edit-points','7');a.input('live-points-reason','Bonificación acordada');await a.click('live-points');const s=readLive(a);assert.equal(s.adjustments[entry.id],7);assert.equal(s.audit.at(-1).kind,'points');assert.equal(a.ctx.OgunLive.view(s).rows.find(r=>r.id===entry.id).points,7);});
test('Controls refuse organizer corrections while a live match is running',async()=>{const a=await liveSetup(4,'knockout',{'t-countdown':'5'});await a.click('live-play');a.input('live-edit-reason','Intento durante emisión');await a.click('live-correct');assert.ok(a.toast.textContent.includes('Pausa'));assert.equal(Object.keys(readLive(a).results).length,0);});
test('A league automatically constructs playoffs and continues through the final',async()=>{const a=await liveSetup(4,'league',{'t-qualify':'4'}),s=await playToEnd(a),v=a.ctx.OgunLive.view(s);assert.equal(v.matches.filter(m=>m.phase==='league').length,6);assert.equal(v.matches.filter(m=>m.phase==='playoff').length,3);assert.ok(v.champion);});
test('Double elimination and group qualification run through the visible live controls',async()=>{for(const format of ['double','groups']){const a=await liveSetup(4,format),s=await playToEnd(a),v=a.ctx.OgunLive.view(s);assert.ok(v.champion,format);assert.ok(a.elements.get('tournament-results').innerHTML.includes(format==='double'?'Cuadro de recuperación':'Grupo 1'));}});
test('Saving, importing and restoring the previous backup preserve the organizer state',async()=>{const a=await liveSetup(3);await a.click('live-save');assert.ok(a.downloads.includes('ogun-torneo-en-directo.json'));const saved=readLive(a),id=saved.entries[0].id;a.change('live-edit-person',id);a.input('live-edit-owner','Nombre nuevo');await a.click('live-rename');assert.ok(readLive(a).entries.some(e=>e.owner==='Nombre nuevo'));await a.click('live-backup');assert.ok(!readLive(a).entries.some(e=>e.owner==='Nombre nuevo'));await a.fileAction('live-import',[red('torneo.json',JSON.stringify(saved))]);assert.equal(readLive(a).seed,saved.seed);const before=a.storage.get('ogun_live_v1');await a.fileAction('live-import',[red('torneo.json','{"type":"invalid"}')]);assert.equal(a.storage.get('ogun_live_v1'),before);assert.ok(a.toast.textContent.includes('compatible'));});
test('Projection mode is available and long or hostile names remain escaped',async()=>{const a=await liveSetup(2),s=readLive(a);a.change('live-edit-person',s.entries[0].id);a.input('live-edit-owner','<img src=x onerror=alert(1)>');await a.click('live-rename');assert.ok(a.elements.get('tournament-results').innerHTML.includes('&lt;img'));assert.ok(!a.elements.get('tournament-results').innerHTML.includes('<img src=x'));await a.click('live-fullscreen');assert.equal(a.ctx.document.body.dataset.broadcast,'true');});
test('Reloading in the middle of a duel preserves completed games and repeats only the interrupted game',async()=>{const a=await liveSetup(2,'knockout');await a.click('live-play');a.advance(80);const partial=readLive(a);assert.equal(partial.checkpoint.games.length,1);await a.click('live-pause');const b=app('#tournaments',null,a.cookieJar,a.sessionMap,a.storage);await b.click('live-play');for(let i=0;i<20;i++)b.advance(80);const done=readLive(b),result=Object.values(done.results)[0];assert.ok(result);assert.equal(result.games.length,2);assert.equal(result.games[0].seed,partial.checkpoint.games[0].seed);assert.equal(result.games[0].firstWarrior,'A');assert.equal(result.games[1].firstWarrior,'B');});
test('Native projection mode remains active when a live match redraws its stage',async()=>{const a=await liveSetup(4),doc=a.ctx.document;doc.documentElement.requestFullscreen=async()=>{doc.fullscreenElement=doc.documentElement;};doc.exitFullscreen=async()=>{doc.fullscreenElement=null;};await a.click('live-fullscreen');assert.equal(doc.fullscreenElement,doc.documentElement);await a.click('live-play');for(let i=0;i<12;i++)a.advance(80);assert.equal(doc.fullscreenElement,doc.documentElement);await a.click('live-fullscreen');assert.equal(doc.fullscreenElement,null);assert.equal(doc.body.dataset.broadcast,'false');});
test('General backup export includes the open live tournament and restores it alongside progress',async()=>{const a=await liveSetup(3),original=readLive(a);await a.click('export-data');const exported=JSON.parse(await a.ctx.lastDownloadBlob.text());assert.equal(exported.liveTournament.seed,original.seed);assert.equal(exported.type,'ogun-backup');const b=app('#settings');await b.fileAction('import-data',[red('mis-datos.json',JSON.stringify(exported))]);const restored=readLive(b);assert.equal(restored.entries.length,3);assert.equal(restored.seed,original.seed);assert.equal(b.ctx.OgunLive.view(restored).complete,false);});
test('A corrupt live tournament in a general backup is rejected without replacing current state',async()=>{const a=await liveSetup(2),before=a.storage.get('ogun_live_v1');await a.click('export-data');const exported=JSON.parse(await a.ctx.lastDownloadBlob.text());exported.liveTournament.schema=999;await a.fileAction('import-data',[red('mis-datos.json',JSON.stringify(exported))]);assert.equal(a.storage.get('ogun_live_v1'),before);assert.ok(a.toast.textContent.includes('compatible'));});
test('A live tournament JSON can be loaded from the empty tournament page',async()=>{const source=await liveSetup(3),raw=readLive(source),a=app('#tournaments');assert.ok(a.root.innerHTML.includes('data-action="live-import"'));await a.fileAction('live-import',[red('copa.json',JSON.stringify(raw))]);assert.equal(readLive(a).entries.length,3);assert.ok(a.root.innerHTML.includes('Cuadro de la competición'));});
test('A corrupt latest autosave falls back to a valid previous copy and remains paused',async()=>{const source=await liveSetup(3),raw=readLive(source),seed=new Map(source.storage);seed.set('ogun_live_previous_v1',JSON.stringify(raw));seed.set('ogun_live_v1','{bad-json');const a=app('#tournaments',null,source.cookieJar,source.sessionMap,seed);assert.equal(readLive(a).seed,raw.seed);assert.ok(a.toast.textContent.includes('copia anterior'));for(let i=0;i<20;i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,0);});
test('Invalid current and previous copies leave the JSON recovery controls accessible',()=>{const seed=new Map([['ogun_live_v1','{bad'],['ogun_live_previous_v1','{bad']]),a=app('#tournaments',null,new Map(),new Map(),seed);assert.ok(a.root.innerHTML.includes('data-action="live-import"'));assert.ok(a.toast.textContent.includes('No se pudo recuperar'));});

test('Workshop is linked from navigation and home, renders every catalog opcode and fixed sandbox',()=>{const a=app('#workshop');assert.ok(a.root.innerHTML.includes('La forja de guerreros'));assert.ok(a.root.innerHTML.includes('href="#workshop"'));for(const op of Object.keys(a.ctx.OgunBlocks.OPS))assert.ok(a.elements.get('work-editor').innerHTML.includes(`data-op="${op}"`),op);assert.ok(a.elements.get('work-validity').textContent.includes('entrada @0'));assert.ok(a.elements.get('work-memory').innerHTML.includes('Celda 0'));assert.ok(a.elements.get('work-processes').textContent.includes('@0'));assert.ok([...a.timers.values()].some(t=>t.delay===900));});
test('A block field updates code, validation and actual execution without replacing the focused input',async()=>{const a=app('#workshop'),field=a.elements.get('wb-5-b');a.input('wb-5-b','2');assert.equal(a.elements.get('wb-5-b'),field);assert.ok(a.storage.get('ogun_workshop_v1').includes('MOV.I $0, $2'));await a.click('work-step');assert.ok(a.elements.get('work-step').innerHTML.includes('copia'));assert.ok(a.elements.get('work-memory').innerHTML.includes('Celda 2: MOV.I'));assert.ok(a.elements.get('work-processes').textContent.includes('@1'));await a.click('work-step');assert.ok(a.elements.get('work-step').innerHTML.includes('Autodestrucción'));});
test('Opcode explanations open a complete dialog including modifier and both address modes',async()=>{const a=app('#workshop');await a.click('work-explain',{index:'5'});const d=a.elements.get('work-help-dialog');assert.equal(d.open,true);assert.ok(d.innerHTML.includes('MOV · Copiar'));assert.ok(d.innerHTML.includes('Instrucción completa'));assert.ok(d.innerHTML.includes('Dirección relativa'));await a.click('work-help-close');assert.equal(d.open,false);});
test('Block modifiers and all address modes update the same generated Redcode',()=>{const a=app('#workshop');a.change('wb-5-aMode','}');a.change('wb-5-bMode','>');a.change('wb-5-mod','X');const code=a.storage.get('ogun_workshop_v1');assert.ok(code.includes('MOV.X }0, >1'));assert.ok(a.elements.get('work-validity').textContent.startsWith('✓'));});
test('Instructions, FOR/ROF, duplicate, remove and accessible reorder actions change real source',async()=>{const a=app('#workshop');await a.click('work-add',{op:'FOR'});let code=a.storage.get('ogun_workshop_v1');assert.ok(code.includes('FOR 4\nROF\nEND'));await a.click('work-copy',{index:'6'});code=a.storage.get('ogun_workshop_v1');assert.equal((code.match(/FOR/g)||[]).length,2);assert.equal((code.match(/ROF/g)||[]).length,2);await a.click('work-remove',{index:'6'});await a.click('work-move',{index:'6',dir:'up'});code=a.storage.get('ogun_workshop_v1');assert.ok(code.indexOf('FOR')<code.indexOf('inicio MOV'));await a.click('work-remove',{index:'5'});assert.ok(!a.storage.get('ogun_workshop_v1').includes('FOR'));});
test('Scratch-style drag moves complete blocks through shipped event handlers',()=>{const a=app('#workshop');a.handlers.dragstart({target:{closest:()=>({dataset:{drag:'5'}})},dataTransfer:{setData(){},effectAllowed:''}});let prevented=false;a.handlers.dragover({preventDefault(){prevented=true;}});a.handlers.drop({target:{closest:()=>({dataset:{blockCard:'4'}})},preventDefault(){}});assert.equal(prevented,true);const code=a.storage.get('ogun_workshop_v1');assert.ok(code.indexOf('inicio MOV')<code.indexOf('ORG inicio'));});
test('Code and blocks round-trip arbitrary library programs and retain invalid lines for correction',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});const source=';name Conservado\nFOR 2\nMOV.I 0, 1\nROF\nEND\n; texto final\n';a.input('work-code',source);await a.click('work-mode',{mode:'blocks'});assert.equal(a.storage.get('ogun_workshop_v1'),source);await a.click('work-mode',{mode:'code'});assert.equal(a.elements.get('work-code').value,source);a.input('work-code','INVALID 1,2');assert.ok(a.elements.get('work-validity').textContent.startsWith('✕'));await a.click('work-mode',{mode:'blocks'});assert.ok(a.elements.get('work-editor').innerHTML.includes('Línea original'));assert.equal(a.storage.get('ogun_workshop_v1'),'INVALID 1,2');});
test('Code editor and block mode expose identical suicide detection and standardized score',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.input('work-code',';name Mortal\nDAT 0,0');await a.click('work-rate');assert.ok(a.elements.get('work-rating-status').textContent.includes('620 combates'));assert.ok(a.elements.get('work-rating-output').innerHTML.includes('Se autodestruye'));assert.ok(a.elements.get('work-rating-output').innerHTML.includes('/ 1000'));const codeResult=a.elements.get('work-rating-output').innerHTML;await a.click('work-mode',{mode:'blocks'});await a.click('work-rate');assert.equal(a.elements.get('work-rating-output').innerHTML,codeResult);});
