test('Navigating from arena retains the separate workshop draft until explicitly importing A or B',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.input('work-code',';name Taller propio\nJMP 0');a.navigate('arena');a.input('code-a',';name Arena propio\nDAT 0,0');a.navigate('workshop');assert.equal(a.elements.get('work-code').value,';name Taller propio\nJMP 0');await a.click('work-from-arena',{side:'a'});assert.equal(a.elements.get('work-code').value,';name Arena propio\nDAT 0,0');});
test('Library examples remain editable blocks, and warriors can be saved, downloaded and sent to play',async()=>{const a=app('#workshop');a.change('work-example','dwarf');assert.ok(a.elements.get('work-validity').textContent.includes('Dwarf'));assert.ok(!a.elements.get('work-editor').innerHTML.includes('Línea original</button>'));await a.click('work-save');assert.equal(JSON.parse(a.storage.get('ogun-v1')).custom[0].name,'Dwarf');await a.click('work-export');assert.ok(a.downloads.includes('ogun-guerrero.red'));assert.equal(await a.ctx.lastDownloadBlob.text(),a.storage.get('ogun_workshop_v1'));await a.click('work-arena');assert.ok(a.elements.get('code-a').value.includes(';name Dwarf'));});
test('RED import preserves syntax including invalid source; errors remain editable and downloadable',async()=>{const a=app('#workshop');await a.fileAction('work-import',[red('bad.red',';name Recuperable\nUNKNOWN 0,0')]);assert.ok(a.elements.get('work-validity').textContent.startsWith('✕'));assert.ok(a.elements.get('work-editor').innerHTML.includes('Línea original'));await a.click('work-export');assert.equal(await a.ctx.lastDownloadBlob.text(),';name Recuperable\nUNKNOWN 0,0');});
test('Worker revisions prevent cancelled or superseded results from showing a stale rating',async()=>{const a=app('#workshop'),workers=[];a.ctx.Worker=class{constructor(url){this.url=url;workers.push(this);}postMessage(m){this.payload=m;}terminate(){this.stopped=true;}};await a.click('work-rate');const first=workers[0];a.input('wb-5-b','2');assert.equal(first.stopped,true);first.onmessage({data:{type:'progress',id:first.payload.id,done:120,total:120,rival:'STALE',solo:{status:'suicide',turns:1,processes:0}}});assert.ok(!a.elements.get('work-rating-status').textContent.includes('STALE'));await a.click('work-rate');const second=workers[1];second.onmessage({data:{type:'progress',id:second.payload.id,done:10,total:120,rival:'Imp',solo:{status:'survives',turns:20000,processes:1}}});assert.ok(a.elements.get('work-rating-status').textContent.includes('10 / 120'));await a.click('work-cancel');assert.equal(second.stopped,true);second.onmessage({data:{type:'error',id:second.payload.id,error:'STALE'}});assert.ok(a.elements.get('work-rating-status').textContent.includes('detenido'));assert.ok(!a.elements.get('work-rating-output').innerHTML.includes('/ 1000'));});
test('Pending debounce is replaced on edits, disabled on request, and cancelled on navigation',async()=>{const a=app('#workshop');const pending=()=>[...a.timers.values()].filter(t=>t.delay===900);assert.equal(pending().length,1);a.input('wb-5-b','2');assert.equal(pending().length,1);a.change('work-auto',false);assert.equal(pending().length,0);a.change('work-auto',true);assert.equal(pending().length,1);a.navigate('home');assert.equal(pending().length,0);});
test('Session preferences preserve view and motion options without persistent preference cookies',async()=>{const a=app('#workshop');a.change('work-auto',false);a.change('work-animate',false);await a.click('work-mode',{mode:'code'});const prefs=JSON.parse(decodeURIComponent(a.cookieJar.get('ogun_workshop')));assert.equal(prefs.mode,'code');assert.equal(prefs.autoRating,false);assert.equal(prefs.autoPreview,false);assert.ok(!a.ctx.lastCookie.includes('Max-Age'));const b=app('#workshop',null,a.cookieJar);assert.ok(b.elements.has('work-code'));assert.equal(b.elements.get('work-auto').checked,false);});
test('Reduced motion prevents automatic preview animation while manual stepping remains available',async()=>{const a=app('#settings');a.change('pref-reduced',true);a.navigate('workshop');a.advance(350);assert.ok(a.elements.get('work-processes').textContent.includes('@0'));await a.click('work-step');assert.ok(a.elements.get('work-processes').textContent.includes('@1'));});
test('Memory navigation inspects wrapped and distant addresses; follow can be restored',async()=>{const a=app('#workshop');a.input('work-address','7999');await a.click('work-inspect');assert.ok(a.elements.get('work-inspector').innerHTML.includes('@7999'));assert.ok(a.elements.get('work-memory').innerHTML.includes('Celda 7999'));a.change('work-follow',true);await a.click('work-step');assert.ok(a.elements.get('work-memory').innerHTML.includes('Celda 1: MOV.I'));await a.click('work-reset');assert.ok(a.elements.get('work-processes').textContent.includes('@0'));});
test('General backup includes the workshop source, restores it and rejects invalid drafts atomically',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.input('work-code',';name Copia\nMOV.I 0,1');a.navigate('settings');await a.click('export-data');const backup=JSON.parse(await a.ctx.lastDownloadBlob.text());assert.equal(backup.workshopDraft,';name Copia\nMOV.I 0,1');const b=app('#settings');await b.fileAction('import-data',[red('copia.json',JSON.stringify(backup))]);b.navigate('workshop');assert.equal(b.storage.get('ogun_workshop_v1'),backup.workshopDraft);backup.workshopDraft={bad:true};b.navigate('settings');await b.fileAction('import-data',[red('copia.json',JSON.stringify(backup))]);assert.ok(b.toast.textContent.includes('Borrador'));assert.equal(b.storage.get('ogun_workshop_v1'),';name Copia\nMOV.I 0,1');});
test('User text is escaped in blocks, execution source, explanations, and saved metadata',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.input('work-code',';name <img src=x onerror=alert(1)>\nMOV.I 0,1 ; <script>alert(1)</script>');await a.click('work-mode',{mode:'blocks'});assert.ok(!a.elements.get('work-editor').innerHTML.includes('<img src=x'));assert.ok(a.elements.get('work-editor').innerHTML.includes('&lt;img'));await a.click('work-step');assert.ok(!a.elements.get('work-step').innerHTML.includes('<script>'));assert.ok(a.elements.get('work-step').innerHTML.includes('&lt;script&gt;'));await a.click('work-explain',{index:'0'});assert.ok(!a.elements.get('work-help-dialog').innerHTML.includes('<img src=x'));});
test('Sending a full workshop warrior to the arena uses matching benchmark rules',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.input('work-code',';assert CORESIZE == 8000\nFOR 120\nJMP 0\nROF');await a.click('work-arena');assert.equal(a.elements.get('cfg-coreSize').value,'8000');assert.equal(a.elements.get('cfg-maxLength').value,'300');await a.click('validate-code',{side:'a'});assert.ok(a.elements.get('validation-a').textContent.startsWith('✓'));});
test('Undo and redo recover block edits and whole FOR segments without crossing arena sides',async()=>{const a=app('#workshop'),original=a.ctx.OgunWorkshop.getDraft();await a.click('work-add',{op:'FOR'});assert.ok(a.storage.get('ogun_workshop_v1').includes('FOR 4\nROF'));await a.click('work-undo');assert.equal(a.storage.get('ogun_workshop_v1'),original);await a.click('work-redo');assert.ok(a.storage.get('ogun_workshop_v1').includes('FOR 4\nROF'));a.navigate('arena');const oldA=a.elements.get('code-a').value;a.input('code-a','DAT 0,0');await a.click('work-undo');assert.equal(a.elements.get('code-a').value,oldA);a.change('work-side','b');const oldB=a.elements.get('code-b').value;await a.click('work-undo');assert.equal(a.elements.get('code-b').value,oldB);a.change('work-side','a');await a.click('work-redo');assert.equal(a.elements.get('code-a').value,'DAT 0,0');});

test('Daily puzzle UI exposes date-specific construction and verified objectives with stable archive solutions',async()=>{const a=app('#home');assert.ok(a.root.innerHTML.includes('construcción única'));await a.click('solution-puzzle');const today=a.elements.get('answer').value;await a.click('check-puzzle');assert.ok(a.elements.get('puzzle-feedback').innerHTML.includes('Objetivo cumplido'));a.navigate('puzzles');a.change('puzzle-date','2026-10-14');const previous=a.root.innerHTML;await a.click('solution-puzzle');await a.click('check-puzzle');assert.ok(a.elements.get('puzzle-feedback').innerHTML.includes('Objetivo cumplido'));a.change('puzzle-date','2026-10-13');assert.notEqual(a.root.innerHTML,previous);assert.ok(a.elements.get('answer'));assert.ok(String(today).length);});
test('Large library paginates, filters level and author, and exposes explained code and exact measured records',async()=>{const a=app('#warriors');assert.ok(a.root.innerHTML.includes('62 estrategias'));assert.equal((a.root.innerHTML.match(/class="panel library-card"/g)||[]).length,12);assert.ok(a.root.innerHTML.includes('chispa del alba'));await a.click('library-page',{page:'1'});assert.ok(!a.root.innerHTML.includes('<h2>chispa del alba</h2>'));a.change('library-author','Sara');const sara=a.ctx.OgunData.warriors.filter(w=>w.author==='Sara').length;assert.ok(a.root.innerHTML.includes(sara+' guerreros'));a.change('library-level','Avanzado');assert.ok(!a.root.innerHTML.includes('class="micro">Inicial</span>'));a.change('library-author','all');a.change('library-level','all');a.input('warrior-search','espada del último juicio');assert.equal((a.root.innerHTML.match(/class="panel library-card"/g)||[]).length,1);assert.ok(a.root.innerHTML.includes('500.000 pasos propios'));assert.ok(a.root.innerHTML.includes('Ver código explicado'));await a.click('library-download',{id:'forja-48'});assert.equal(await a.ctx.lastDownloadBlob.text(),a.ctx.OgunData.warriors.find(w=>w.id==='forja-48').code);});
test('All fifty bank warriors load in blocks without losing annotations or creating invalid raw blocks',()=>{const a=app('#workshop');for(const w of a.ctx.OgunData.warriors.filter(w=>w.collection==='forja')){a.change('work-example',w.id);assert.ok(a.elements.get('work-validity').textContent.startsWith('✓'),w.name);assert.equal(a.storage.get('ogun_workshop_v1'),w.code);assert.ok(!a.ctx.OgunBlocks.parse(w.code).some(b=>b.op==='RAW'),w.name);assert.ok(a.elements.get('work-editor').innerHTML.includes('data-op="MOV"'));}assert.equal([...a.timers.values()].filter(t=>t.delay===900).length,1);});
test('Library opens a chosen warrior directly in block mode, even after code was selected',async()=>{const a=app('#workshop');await a.click('work-mode',{mode:'code'});a.navigate('warriors');await a.click('library-blocks',{id:'forja-49'});assert.ok(a.elements.has('work-stack'));assert.equal(a.storage.get('ogun_workshop_v1'),a.ctx.OgunData.warriors.find(w=>w.id==='forja-49').code);assert.ok(a.elements.get('work-validity').textContent.includes('nexo del apocalipsis'));});
test('Adding the compatible bank respects P-space admission and prepares the fifty-person bracket',async()=>{const a=app('#tournaments');await a.click('tournament-bank');assert.ok(a.root.innerHTML.includes('46 / 64 VÁLIDOS'));a.change('t-allow-pspace',true);await a.click('tournament-bank');assert.ok(a.root.innerHTML.includes('50 / 64 VÁLIDOS'));a.change('t-format','knockout');a.change('t-countdown','0');a.change('t-intermission','0');a.change('t-live-announcements','off');a.change('t-turns','6');a.change('t-rounds','2');a.change('t-knockout-tie','seeded');await a.click('prepare-live');const state=readLive(a);assert.equal(state.entries.length,50);assert.equal(a.ctx.OgunLive.view(state).matches.filter(m=>m.status==='bye').length,14);assert.ok(a.root.innerHTML.includes('bracket-connectors'));const done=await playToEnd(a);assert.equal(Object.keys(done.results).length,49);assert.ok(a.elements.get('tournament-results').innerHTML.includes('CAMPEÓN'));});
test('Tournament library search preserves checked selection and session recovery',async()=>{const a=app('#tournaments');a.change('t-allow-pspace',true);await a.click('tournament-bank');a.input('t-library-search','nexo del apocalipsis');assert.ok(a.elements.get('t-library-list').innerHTML.includes('nexo del apocalipsis'));assert.ok(!a.elements.get('t-library-list').innerHTML.includes('chispa del alba'));const b=app('#tournaments',null,a.cookieJar,a.sessionMap);assert.ok(b.root.innerHTML.includes('50 / 64 VÁLIDOS'));await b.click('tournament-clear');assert.ok(b.root.innerHTML.includes('0 / 64 VÁLIDOS'));});
test('Manual winner announcements stay open despite elapsed time, Escape and backdrop; Continue acknowledges',async()=>{const a=app('#settings');assert.equal(a.elements.get('pref-resultManual').checked,true);for(const action of['preview-win','preview-draw']){await a.click(action);assert.equal(a.resultLayer.dataset.effect,'nova');assert.ok(a.resultLayer.innerHTML.includes('Pulsa Continuar para seguir'));assert.ok(!a.resultLayer.innerHTML.includes('id="result-skip"'));a.advance(60000);assert.equal(a.resultLayer.classList.contains('hidden'),false);a.key('Escape');a.resultClick(null);assert.equal(a.resultLayer.classList.contains('hidden'),false);a.resultClick('close');assert.equal(a.resultLayer.classList.contains('hidden'),true);}});
test('Optional automatic closing and all new effects honor timing, color, motion and session preferences',async()=>{const a=app('#settings');a.change('pref-resultManual',false);a.change('pref-resultDuration','1000');a.change('pref-resultTempo','2400');a.change('pref-winA','#11aabb');for(const style of['nova','forge','laurel']){a.change('pref-resultStyle',style);await a.click('preview-win');assert.equal(a.resultLayer.dataset.effect,style);assert.equal(a.resultLayer.style['--result-tempo'],'2400ms');assert.equal(a.resultLayer.style['--result-color'],'#11aabb');a.advance(1001);assert.equal(a.resultLayer.classList.contains('hidden'),true);}a.change('pref-reduced',true);await a.click('preview-draw');assert.equal(a.resultLayer.dataset.effect,'still');const b=app('#settings',null,a.cookieJar);assert.equal(b.elements.get('pref-resultManual').checked,false);assert.equal(b.elements.get('pref-resultTempo').value,'2400');});
test('Live tournament cannot advance past a displayed result until Continue is pressed',async()=>{const a=await liveSetup(4,'knockout',{'t-live-announcements':'duels'});await a.click('live-play');for(let i=0;i<15&&!a.resultLayer.innerHTML.includes('VICTORIA')&&!a.resultLayer.innerHTML.includes('EMPATE');i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,1);for(let i=0;i<50;i++)a.advance(1000);assert.equal(Object.keys(readLive(a).results).length,1);a.resultClick('close');for(let i=0;i<12;i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,2);a.resultClick('close');for(let i=0;i<12;i++)a.advance(80);assert.equal(Object.keys(readLive(a).results).length,3);});
test('Measured wins against the dark sage can be found without inventing unbeaten status',()=>{const a=app('#warriors');a.change('library-collection','sabio');const winners=a.ctx.OgunData.warriors.filter(w=>w.validation?.vsSabio.wins>0);assert.ok(winners.length>0);assert.ok(a.root.innerHTML.includes(winners.length+' guerreros'));for(const w of winners)assert.ok(a.root.innerHTML.includes(w.name));assert.ok(a.root.innerHTML.includes('empate')||a.root.innerHTML.includes(' E · '));});
test('Home always shows the current Madrid daily even after exploring an older archive date',()=>{const a=app('#puzzles');a.change('puzzle-date','2026-10-13');assert.ok(a.root.innerHTML.includes('2026-10-13'));a.navigate('home');const today=a.ctx.OgunChallenges.madridDate();assert.ok(a.root.innerHTML.includes('Generado para '+today));});
